    long long val;
    Node* left = nullptr;
    Node* right = nullptr;
    Node(long long v) : val(v) {}
};

// Builds a tree from a level-order array where -1 marks a null child.
Node* buildTree(vector<long long>& vals) {
    if (vals.empty() || vals[0] == -1) return nullptr;
    Node* root = new Node(vals[0]);
    queue<Node*> q;
    q.push(root);
    size_t i = 1;
    while (!q.empty() && i < vals.size()) {
        Node* cur = q.front(); q.pop();
        if (i < vals.size()) {
            long long lv = vals[i++];
            if (lv != -1) { cur->left = new Node(lv); q.push(cur->left); }
        }
        if (i < vals.size()) {
            long long rv = vals[i++];
            if (rv != -1) { cur->right = new Node(rv); q.push(cur->right); }
        }
    }
    return root;
}

